        css: [common.css, match.css].filter((s) => s).join('\n'),
        ignoreInlineStyle: common.ignoreInlineStyle.concat(match.ignoreInlineStyle || []),
        ignoreImageAnalysis: common.ignoreImageAnalysis.concat(match.ignoreImageAnalysis || []),
    };
}

